class APISettings:
    def __init__(self, user_settings, defaults, other):
        self.CONSUMER_KEY = user_settings.get('CONSUMER_KEY', defaults['CONSUMER_KEY'])
        self.CONSUMER_SECRET = user_settings.get('CONSUMER_SECRET', defaults['CONSUMER_SECRET'])
        self.HOST_NAME = user_settings.get('HOST_NAME', defaults['HOST_NAME'])
        self.PASS_KEY = user_settings.get('PASS_KEY', defaults['PASS_KEY'])
        self.SHORT_CODE = user_settings.get('SHORT_CODE', defaults['SHORT_CODE'])
        self.TILL_NUMBER = user_settings.get('TILL_NUMBER', defaults['TILL_NUMBER'])
        self.SAFARICOM_API = user_settings.get('SAFARICOM_API', defaults['SAFARICOM_API'])
        self.TRANSACTION_TYPE = user_settings.get('TRANSACTION_TYPE', defaults['TRANSACTION_TYPE'])
        self.AUTH_URL = user_settings.get('AUTH_URL', defaults['AUTH_URL'])

